<?php
require_once __DIR__.'/includes/auth.php';require_permission('settings');$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['form_action']??'';$id=(int)($_POST['id']??0);if($action==='save'){$position=trim($_POST['position_title']??'');$name=trim($_POST['full_name']??'');$address=trim($_POST['address']??'');$term=trim($_POST['term_end']??'');$contact=trim($_POST['contact_number']??'');$active=isset($_POST['is_active'])?1:0;if($position===''||$name===''||$address===''||$term===''||$contact===''){flash('error','Position, name, address, term end, and contact number are required.');redirect('elected_officials.php');}if($id){$pdo->prepare('UPDATE elected_officials SET position_title=?,full_name=?,address=?,term_end=?,contact_number=?,is_active=? WHERE id=?')->execute([$position,$name,$address,$term,$contact,$active,$id]);audit_action('elected_official_updated','elected_officials',$id,$position.' · '.$name);}else{$pdo->prepare('INSERT INTO elected_officials (position_title,full_name,address,term_end,contact_number,is_active,created_by) VALUES (?,?,?,?,?,?,?)')->execute([$position,$name,$address,$term,$contact,$active,current_user()['id']]);audit_action('elected_official_created','elected_officials',(int)$pdo->lastInsertId(),$position.' · '.$name);}flash('success','Elected official profile saved.');redirect('elected_officials.php');}if($action==='archive'&&$id){$pdo->prepare('UPDATE elected_officials SET is_active=0 WHERE id=?')->execute([$id]);audit_action('elected_official_archived','elected_officials',$id);flash('success','Official profile archived from the sidebar. The record was retained.');redirect('elected_officials.php');}}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM elected_officials WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$officials=$pdo->query('SELECT * FROM elected_officials ORDER BY is_active DESC,sort_order,position_title')->fetchAll();$pageTitle='Elected officials';$activePage='officials';require __DIR__.'/partials/header.php';
?><section class="section-heading"><div><div class="eyebrow">Administration / Governance</div><h1>Elected officials</h1><p>Maintain the official profiles shown in the sidebar. Archive former officials when their term ends; deletion is disabled.</p></div><a class="primary-button" href="elected_officials.php?action=new">＋ Add official</a></section><?php if(($_GET['action']??'')==='new'||$edit): ?><section class="panel form-panel"><div class="card-header"><h2><?= $edit?'Edit official profile':'Add official profile' ?></h2><a class="text-button" href="elected_officials.php">Close ×</a></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="form_action" value="save"><input type="hidden" name="id" value="<?= h($edit['id']??'') ?>"><label>Position<input name="position_title" required value="<?= h($edit['position_title']??'') ?>" placeholder="Punong Barangay"></label><label>Full name<input name="full_name" required value="<?= h($edit['full_name']??'') ?>"></label><label class="wide">Official address<input name="address" required value="<?= h($edit['address']??'') ?>"></label><label>End of term<input type="date" name="term_end" required value="<?= h($edit['term_end']??'') ?>"></label><label>Contact number<input name="contact_number" required value="<?= h($edit['contact_number']??'') ?>"></label><label class="check-field"><input type="checkbox" name="is_active" <?= !isset($edit['is_active'])||$edit['is_active']?'checked':'' ?>> Show in official sidebar</label><div class="form-actions"><a class="secondary-button" href="elected_officials.php">Cancel</a><button class="primary-button">Save official</button></div></form></section><?php endif; ?><section class="panel table-panel"><div class="table-toolbar"><div><div class="eyebrow">Official register</div><h2>Term and contact records</h2></div><span class="muted"><?= count($officials) ?> retained profiles</span></div><div class="table-wrap"><table><thead><tr><th>Position / name</th><th>Address</th><th>End of term</th><th>Contact</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($officials as $official): ?><tr><td><strong><?= h($official['position_title']) ?></strong><small class="cell-subtext"><?= h($official['full_name']) ?></small></td><td><?= h($official['address']) ?></td><td class="muted"><?= h(date('M d, Y',strtotime($official['term_end']))) ?></td><td><?= h($official['contact_number']) ?></td><td><span class="status-pill <?= $official['is_active']?'active':'archived' ?>"><i></i><?= $official['is_active']?'Active':'Archived' ?></span></td><td><a class="text-button" href="elected_officials.php?edit=<?= h($official['id']) ?>">Edit</a><?php if($official['is_active']): ?><form method="post" class="inline-form" onsubmit="return confirm('Archive this official from the sidebar? The record will be retained.')"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="form_action" value="archive"><input type="hidden" name="id" value="<?= h($official['id']) ?>"><button class="archive-button" type="submit">Mark as archived</button></form><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$officials): ?><tr><td colspan="6" class="empty-state">No elected officials configured yet. Add the approved official profiles to show them in the sidebar.</td></tr><?php endif; ?></tbody></table></div></section><?php require __DIR__.'/partials/footer.php'; ?>
